.stats > div {
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--sunken);
}

.stats strong {
  font-size: 20px;
  color: var(--fg-strong);
}

.stats span {
  font-size: 12px;
}

.stats .tags {
  grid-column: 1 / -1;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0;
  background: none;
