.tag {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.jobs {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.jobs li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--sunken);
  font-size: 13px;
}

.pill {
  min-width: 64px;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  text-align: center;
}

.pill.queued {
  background: var(--warning-soft);
  color: var(--warning);
}

.pill.running {
  background: var(--accent-soft);
  color: var(--accent);
}

.pill.success {
  background: var(--success-soft);
  color: var(--success);
}

.pill.failure {
  background: var(--error-soft);
  color: var(--error);
}

.bar {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background: var(--border);
  overflow: hidden;
}

.bar-fill {
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}

.bar-fill.running {
  animation: fill linear forwards;
}

.bar-fill.success {
  width: 100%;
  background: var(--success);
}

.bar-fill.failure {
  width: 100%;
  background: var(--error);
}

@keyframes fill {
  to {
    width: 95%;
  }
}

