  font-size: 15px;
  font-weight: 600;
}

.card-header p {
  margin: 2px 0 0;
  font-size: 13px;
}

.card-step {
  flex: none;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}

.card-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px 18px;
}

.snippet {
  margin: 0;
  padding: 10px 18px;
  border-top: 1px solid var(--border);
  background: var(--sunken);
  color: var(--muted);
  font-size: 12px;
  white-space: pre-wrap;
}

.row {
  display: flex;
  gap: 8px;
}

input,
textarea {
  flex: 1;
  min-width: 0;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--card);
  color: var(--fg-strong);
  font: inherit;
  resize: vertical;
}

input:focus,
textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: -1px;
}

button {
  padding: 7px 14px;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
}

button:hover:not(:disabled) {
  background: var(--accent-hover);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.output {
  min-height: 44px;
  padding: 11px 12px;
  border-radius: 6px;
  background: var(--sunken);
  word-break: break-word;
}

.output.error {
  background: var(--error-soft);
}

.output.stream {
  min-height: 96px;
  white-space: pre-wrap;
}

.caret {
  display: inline-block;
  width: 7px;
  height: 1em;
  margin-left: 2px;
  vertical-align: text-bottom;
  background: var(--accent);
  animation: blink 1s steps(1) infinite;
}

@keyframes blink {
  50% {
    opacity: 0;
  }
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stats > div {
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: 6px;
  background: var(--sunken);
}

.stats strong {
  font-size: 20px;
  color: var(--fg-strong);
}

.stats span {
  font-size: 12px;
}

.stats .tags {
  grid-column: 1 / -1;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0;
  background: none;
}

.tag {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.jobs {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.jobs li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--sunken);
  font-size: 13px;
}

.pill {
  min-width: 64px;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  text-align: center;
}

.pill.queued {
  background: var(--warning-soft);
  color: var(--warning);
}

.pill.running {
  background: var(--accent-soft);
  color: var(--accent);
}

.pill.success {
  background: var(--success-soft);
  color: var(--success);
}

.pill.failure {
  background: var(--error-soft);
  color: var(--error);
}

.bar {
  flex: 1;
  height: 4px;
  border-radius: 999px;
  background: var(--border);
  overflow: hidden;
}

.bar-fill {
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}

.bar-fill.running {
  animation: fill linear forwards;
}

.bar-fill.success {
  width: 100%;
  background: var(--success);
}

.bar-fill.failure {
  width: 100%;
  background: var(--error);
}

@keyframes fill {
  to {
    width: 95%;
  }
}

